    found_unrooted=[];found_rooted=[];notfound=[]
    for c in cands:
        if c in index:
            mods={m for m,_,_ in index[c]}
            if mods & unrooted and not (mods-unrooted): found_unrooted.append((c,sorted(mods)))
            else: found_rooted.append(c)
        else:
            notfound.append(c)
    # also files by basename
    fb=[]
    for f in re.findall(r'\b([A-Z][A-Za-z0-9]*\.lean)\b', s):
        mods=basen.get(f)
        if not mods: fb.append((f,'NO SUCH FILE'))
        elif all(m in unrooted for m in mods): fb.append((f,'UNROOTED'))
    print(f"== {k}")
    if fb: print("   file-refs:", fb)
    if found_unrooted: print("   DECL ONLY IN UNROOTED:", found_unrooted)
    if notfound: print("   NO DECL FOUND for tokens:", notfound[:25])
EOF

