import os,re,json
root='.'
def strip(txt):
    out=[];i=0;depth=0
    while i<len(txt):
        if txt.startswith('/-',i): depth+=1;i+=2;continue
        if txt.startswith('-/',i) and depth: depth-=1;i+=2;continue
        if depth: i+=1;continue
        if txt.startswith('--',i):
            j=txt.find('\n',i); i=len(txt) if j<0 else j; continue
        out.append(txt[i]); i+=1
    return ''.join(out)
res={}
tot=0
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    if '.lake' in dp: continue
    for f in fn:
        if not f.endswith('.lean'): continue
        p=os.path.join(dp,f)
        t=strip(open(p,errors='replace').read())
        n=len(re.findall(r'(?<![A-Za-z_.])sorry(?![A-Za-z_])',t))
        if n: res[p]=n; tot+=n
print('AJC modules with real sorry:',len(res),'total sorries:',tot)
for k,v in sorted(res.items()): print(' ',v,k)
EOF
